import { useEffect, useState } from "react";

const API_BASE = "http://localhost:5000/api";
const API_STUDENTS = `${API_BASE}/students`;
const API_COURSES = `${API_BASE}/courses`;
const API_RESULTS = `${API_BASE}/results`;

export default function Results() {
  const [students, setStudents] = useState([]);
  const [courses, setCourses] = useState([]);
  const [results, setResults] = useState([]);
  const [form, setForm] = useState({ studentId: "", courseId: "", marks: "", grade: "" });
  const [editingId, setEditingId] = useState(null);
  const [error, setError] = useState("");

  // Load data
  useEffect(() => {
    const fetchData = async () => {
      try {
        // Fetch students
        const studentsRes = await fetch(API_STUDENTS);
        if (!studentsRes.ok) throw new Error('Failed to fetch students');
        const studentsData = await studentsRes.json();
        console.log('Fetched students:', studentsData);
        setStudents(studentsData);

        // Fetch courses
        const coursesRes = await fetch(API_COURSES);
        if (!coursesRes.ok) throw new Error('Failed to fetch courses');
        const coursesData = await coursesRes.json();
        console.log('Fetched courses:', coursesData);
        setCourses(coursesData);

        // Fetch results
        const resultsRes = await fetch(API_RESULTS);
        if (!resultsRes.ok) throw new Error('Failed to fetch results');
        const resultsData = await resultsRes.json();
        console.log('Fetched results:', resultsData);
        setResults(resultsData);
      } catch (err) {
        console.error('Error fetching data:', err);
        setError(`Error loading data: ${err.message}`);
      }
    };

    fetchData();
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const resetForm = () => {
    setForm({ studentId: "", courseId: "", marks: "", grade: "" });
    setEditingId(null);
    setError("");
  };

  // Add or Update
  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await fetch(
        editingId ? `${API_RESULTS}/${editingId}` : API_RESULTS,
        {
          method: editingId ? "PUT" : "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify(form),
        }
      );
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || "Action failed");

      // Update table
      if (editingId) {
        setResults(results.map((r) => (r._id === editingId ? data.result : r)));
      } else {
        setResults([...results, data.result]);
      }
      resetForm();
    } catch (err) {
      setError(err.message);
    }
  };

  const startEdit = (result) => {
    setEditingId(result._id);
    setForm({
      studentId: result.student._id,
      courseId: result.course._id,
      marks: result.marks,
      grade: result.grade,
    });
  };

  return (
    <div className="container mt-4">
      <h2>Student Results</h2>
      {error && <div className="alert alert-danger">{error}</div>}

      <form onSubmit={handleSubmit} className="row g-2 mb-4">
        <div className="col-md-3">
          <select
            className="form-select"
            name="studentId"
            value={form.studentId}
            onChange={handleChange}
            required
          >
            <option value="">Select Student</option>
            {students.map((s) => (
              <option key={s._id} value={s._id}>{s.name}</option>
            ))}
          </select>
        </div>

        <div className="col-md-3">
          <select
            className="form-select"
            name="courseId"
            value={form.courseId}
            onChange={handleChange}
            required
          >
            <option value="">Select Course</option>
            {courses.map((c) => (
              <option key={c._id} value={c._id}>{c.name}</option>
            ))}
          </select>
        </div>

        <div className="col-md-2">
          <input
            type="number"
            className="form-control"
            name="marks"
            placeholder="Marks"
            value={form.marks}
            onChange={handleChange}
            required
          />
        </div>

        <div className="col-md-2">
          <input
            type="text"
            className="form-control"
            name="grade"
            placeholder="Grade"
            value={form.grade}
            onChange={handleChange}
            required
          />
        </div>

        <div className="col-md-2">
          <button type="submit" className="btn btn-primary">
            {editingId ? "Update Result" : "Add Result"}
          </button>
          {editingId && <button type="button" className="btn btn-secondary ms-2" onClick={resetForm}>Cancel</button>}
        </div>
      </form>

      <table className="table table-striped">
        <thead>
          <tr>
            <th>#</th>
            <th>Student Name</th>
            <th>Course Name</th>
            <th>Marks</th>
            <th>Grade</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {results.map((r, idx) => (
            <tr key={r._id}>
              <td>{idx + 1}</td>
              <td>{r.student.name}</td>
              <td>{r.course.name}</td>
              <td>{r.marks}</td>
              <td>{r.grade}</td>
              <td>
                <button className="btn btn-sm btn-outline-primary me-2" onClick={() => startEdit(r)}>Edit</button>
              </td>
            </tr>
          ))}
          {results.length === 0 && (
            <tr>
              <td colSpan="6" className="text-center text-muted">No results yet</td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
